<?php require_once 'app.php'; require_login();$s=db()->prepare('SELECT * FROM transacoes WHERE usuario_id=? ORDER BY data_lancamento DESC,id DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();layout_start('Transações');?><div class="d-flex justify-content-between mb-3"><span class="text-muted"><?=count($rows)?> lançamentos</span><a href="registro_gastos.php" class="btn btn-primary">Novo lançamento</a></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Tipo</th><th class="text-end">Valor</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['data_lancamento']))?></td><td><?=e($r['descricao'])?></td><td><?=e($r['categoria'])?></td><td><span class="badge bg-<?=$r['tipo']==='receita'?'success':'danger'?>"><?=ucfirst($r['tipo'])?></span></td><td class="text-end"><?=money($r['valor'])?></td><td><form method="post" action="excluir_item.php" onsubmit="return confirm('Excluir lançamento?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="text-muted mb-0">Nenhum lançamento encontrado.</p><?php endif;?></div><?php layout_end();